import{_ as p,a0 as u,w as o,s as l,ao as s,I as i,x as t,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧：一款轻量级的Email阅读器Geary | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：一款轻量级的Email阅读器Geary | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：一款轻量级的Email阅读器Geary | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：一款轻量级的Email阅读器Geary | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu","title":"每日Ubuntu小技巧：一款轻量级的Email阅读器Geary","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu.md","filePath":"[post].md"}'),d={name:"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu.md"};function m(g,e,y,b,T,G){const a=u("Link");return o(),l("div",null,[e[11]||(e[11]=s(`<h1 id="每日ubuntu小技巧-一款轻量级的email阅读器geary" tabindex="-1">每日Ubuntu小技巧：一款轻量级的Email阅读器Geary <a class="header-anchor" href="#每日ubuntu小技巧-一款轻量级的email阅读器geary" aria-label="Permalink to “每日Ubuntu小技巧：一款轻量级的Email阅读器Geary”">​</a></h1><p>正如大家所知，Ubuntu 本身自带可以收发邮件的客户端——Thunderbird，当然它也支持Gmail，Yahoo Mail，Microsoft Outlook 等等支持IMAP协议的邮件服务。</p><p>Thunderbird 是一个功能强大的邮件客户端，只要email客户端所需要的功能，它都能够做到。但是如果你想选择一个能在够在GNOME 下运行的轻量级客户端，Geary 是一个不错的选择。</p><p>Geary 是一个界面简洁，能让你快捷方便的地阅读邮件的免费程序。它所有的对话均展示在一个简洁的面板上，这样你可以不必点击鼠标来切换消息。</p><p>Geary 还支持IMAP 协议，所以你可以使用Google, Yahoo 和 Microsoft 这样的在线邮箱服务。</p><p>以Ubuntu 13.10用户为例，Geary 可以在Ubuntu 的软件中心获取。只要运行以下命令即可安装Geary 。</p><pre><code>sudo apt-get install geary
</code></pre><p>在以前的Ubuntu 版本中，键盘按下<strong>Ctrl – Alt – T</strong> 可以打开终端。打开之后，运行以下命令增加PPA源。</p><pre><code>sudo add-apt-repository ppa:yorba/ppa
</code></pre><p>接下来运行以下命令来升级系统和安装Geary 。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install geary
</code></pre><p>第一次启动Geary时，你需要设置你的Gmail，Yahoo 或 Microsoft 电子邮件帐户。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/gearyubuntu.png" alt=""></p><p>设置非常的简单，只要输入你的账号信息，Geary 就会自动配置好你的账号。</p><p>若想卸载Geary ，首先要从系统中移除它的PPA源，要运行的命令如下。</p><pre><code>sudo add-apt-repository -r ppa:yorba/ppa
</code></pre><p>然后再运行以下命令卸载Geary 。</p><pre><code>sudo apt-get remove geary 
</code></pre><p>就这么简单~</p><hr>`,20)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-get-geary-a-lightweight-email-reader-in-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-get-geary-a-lightweight-email-reader-in-ubuntu/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("译者：",-1)),r(a,{href:"https://github.com/NearTan"},{default:n(()=>[...e[2]||(e[2]=[t("NearTan",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),r(a,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const U=p(d,[["render",m]]);export{w as __pageData,U as default};
